                      display: "grid",
                      placeItems: "center",
                    }}
                  >
                    <Icon type={c} size={18} />
                  </div>

                  <div>
                    <strong style={{ display: "block", marginBottom: 4 }}>
                      {a}
                    </strong>
                    <span
                      style={{
                        fontSize: 13,
                        lineHeight: 1.5,
                        color: "#a9bdc9",
                      }}
                    >
                      {b}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          </div>

          <img
            src="https://images.unsplash.com/photo-1552664730-d307ca884978?auto=format&fit=crop&w=1100&q=85"
            alt="Vighnex Technologies business team"
            loading="lazy"
            style={{
              width: "100%",
              height: 560,
              objectFit: "cover",
              borderRadius: 30,
              display: "block",
              boxShadow: "0 25px 60px rgba(0,0,0,.2)",
            }}
          />
        </div>
      </section>

      <section id="technology" style={section}>
        <div style={container}>
          <div style={title}>
            <div style={eyebrow}>Technology Stack</div>
            <h2
              style={{
                fontFamily: "Georgia,serif",
                fontSize: "clamp(36px,5vw,58px)",
                lineHeight: 1.05,
                color: "#092338",
                marginBottom: 18,
              }}
            >
              Built with technology that moves forward.
            </h2>
            <p style={{ fontSize: 17, lineHeight: 1.8, color: "#637181" }}>
              We choose tools based on the problem, not trends. Our stack
              supports fast development today and sustainable growth tomorrow.
            </p>
          </div>

          <div
            style={{
              display: "flex",
              flexWrap: "wrap",
              justifyContent: "center",
              gap: 12,
              maxWidth: 900,
              margin: "auto",
            }}
          >
            {technologies.map(([a, b]) => (
              <div
                key={a}
                style={{
                  background: "#fff",
                  border: "1px solid #e9e0d0",
                  padding: "16px 21px",
                  borderRadius: 15,
                  display: "flex",
                  gap: 9,
                  alignItems: "center",
                }}
              >
                <span
                  style={{
                    width: 9,
                    height: 9,
                    borderRadius: "50%",
                    background: "#c89032",
                  }}
                />
                <strong>{a}</strong>
                <small style={{ color: "#85909b" }}>{b}</small>
              </div>
            ))}
          </div>
        </div>
      </section>

      <section
        id="process"
        style={{
          ...section,
          background: "#f3ecdf",
        }}
      >
        <div style={container}>
          <div style={title}>
            <div style={eyebrow}>Our Process</div>
            <h2
              style={{
                fontFamily: "Georgia,serif",
                fontSize: "clamp(36px,5vw,58px)",
                lineHeight: 1.05,
                color: "#092338",
                marginBottom: 18,
              }}
            >
              From first conversation to lasting impact.
            </h2>
            <p style={{ fontSize: 17, lineHeight: 1.8, color: "#637181" }}>
              A structured process keeps creativity focused, development
              predictable and every decision connected to your goals.
            </p>
          </div>

          <div
            style={{
              display: "grid",
              gridTemplateColumns: "repeat(auto-fit,minmax(160px,1fr))",
              gap: 25,
            }}
          >
            {process.map(([num, name, text, icon]) => (
              <div
                key={name}
                style={{
                  textAlign: "center",
                  padding: 10,
                }}
              >
                <div
                  style={{
                    color: "#c89032",
                    fontFamily: "Georgia,serif",
                    fontSize: 13,
                    marginBottom: 10,
                  }}
                >
                  {num}
                </div>

                <div
                  style={{
                    width: 70,
                    height: 70,
                    borderRadius: "50%",
                    border: "1px solid #e1c78d",
                    background: "#fff",
                    margin: "0 auto 17px",
                    display: "grid",
                    placeItems: "center",
                    color: "#c89032",
                  }}
                >
                  <Icon type={icon} size={28} />
                </div>

                <h3
                  style={{
                    fontFamily: "Georgia,serif",
                    marginBottom: 8,
                  }}
                >
                  {name}
                </h3>

                <p
                  style={{
                    fontSize: 12,
                    lineHeight: 1.6,
                    color: "#637181",
                  }}
                >
                  {text}
                </p>
              </div>
            ))}
          </div>
        </div>
      </section>

      <section
        style={{
          background: "#092338",
          color: "#fff",
          padding: "65px 0",
        }}
      >
        <div
          style={{
            ...container,
            display: "grid",
            gridTemplateColumns: "repeat(auto-fit,minmax(180px,1fr))",
            textAlign: "center",
          }}
        >
          {[
            ["50+", "Digital Ideas Transformed"],
            ["100+", "Projects & Deliverables"],
            ["24/7", "Digital Possibilities"],
            ["100%", "Commitment to Quality"],
          ].map(([a, b]) => (
            <div key={b} style={{ padding: 20 }}>
              <strong
                style={{
                  fontFamily: "Georgia,serif",
                  fontSize: 48,
                  color: "#e6b85c",
                  display: "block",
                }}
              >
                {a}
              </strong>
              <span style={{ fontSize: 13, color: "#bdcdd6" }}>{b}</span>
            </div>
          ))}
        </div>
      </section>

      <section id="projects" style={section}>
        <div style={container}>
          <div style={title}>
            <div style={eyebrow}>Selected Work</div>
            <h2
              style={{
                fontFamily: "Georgia,serif",
                fontSize: "clamp(36px,5vw,58px)",
                color: "#092338",
                marginBottom: 18,
              }}
            >
              Ideas become experiences.
            </h2>
            <p style={{ fontSize: 17, lineHeight: 1.8, color: "#637181" }}>
              A glimpse into the kind of digital experiences we love creating.
            </p>
          </div>

          <div
            style={{
              display: "grid",
              gridTemplateColumns: "repeat(auto-fit,minmax(280px,1fr))",
              gap: 22,
            }}
          >
            {projects.map((project) => (
              <div
                key={project.title}
                style={{
                  background: "#fff",
                  borderRadius: 22,
                  overflow: "hidden",
                  boxShadow: "0 10px 35px rgba(25,43,60,.08)",
                }}
              >
                <img
                  src={poster}
                  alt={project.title}
                  loading="lazy"
                  style={{
                    width: "100%",
                    height: 240,
                    objectFit: "cover",
                    display: "block",
                  }}
                />

                <div style={{ padding: 25 }}>
                  <div
                    style={{
                      fontSize: 10,
                      color: "#c89032",
                      fontWeight: 800,
                      letterSpacing: 2,
                    }}
                  >
                    {project.category}
                  </div>

                  <h3
                    style={{
                      fontFamily: "Georgia,serif",
                      fontSize: 27,
                      margin: "8px 0",
                    }}
                  >
                    {project.title}
                  </h3>

                  <p
                    style={{
                      fontSize: 13,
                      lineHeight: 1.7,
                      color: "#637181",
                      marginBottom: 17,
                    }}
                  >
                    {project.text}
                  </p>

                  <button
                    onClick={() => scrollTo("contact")}
                    style={{
                      border: 0,
                      background: "transparent",
                      color: "#092338",
                      fontWeight: 800,
                      cursor: "pointer",
                      display: "flex",
                      alignItems: "center",
                      gap: 7,
                    }}
                  >
                    Discuss a Similar Project <Icon type="arrow" size={15} />
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>

      <section
        id="testimonials"
        style={{
          ...section,
          background: "#f3ecdf",
        }}
      >
        <div style={container}>
          <div style={title}>
            <div style={eyebrow}>Client Voices</div>
            <h2
              style={{
                fontFamily: "Georgia,serif",
                fontSize: "clamp(36px,5vw,58px)",
                color: "#092338",
                marginBottom: 18,
              }}
            >
              Built on trust. Remembered for results.
            </h2>
            <p style={{ fontSize: 17, lineHeight: 1.8, color: "#637181" }}>
              Strong partnerships are at the center of everything we build.
            </p>
          </div>

          <div
            style={{
              display: "grid",
              gridTemplateColumns: "repeat(auto-fit,minmax(280px,1fr))",
              gap: 22,
            }}
          >
            {testimonials.map((item) => (
              <div
                key={item.name}
                style={{
                  background: "#fff",
                  border: "1px solid #eee5d7",
                  borderRadius: 22,
                  padding: 30,
                }}
              >
                <div
                  style={{
                    color: "#c89032",
                    display: "flex",
                    gap: 2,
                    marginBottom: 20,
                  }}
                >
                  {[1, 2, 3, 4, 5].map((i) => (
                    <Icon key={i} type="star" size={15} />
                  ))}
                </div>

                <p
                  style={{
                    fontFamily: "Georgia,serif",
                    fontSize: 18,
                    lineHeight: 1.65,
                    color: "#33495b",
                    marginBottom: 25,
                  }}
                >
                  “{item.text}”
                </p>

                <div
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 13,
                  }}
                >
                  <img
                    src={item.image}
                    alt={item.name}
                    loading="lazy"
                    style={{
                      width: 52,
                      height: 52,
                      borderRadius: "50%",
                      objectFit: "cover",
                    }}
                  />

                  <div>
                    <strong style={{ display: "block", color: "#092338" }}>
                      {item.name}
                    </strong>
                    <span style={{ fontSize: 11, color: "#637181" }}>
                      {item.role}
                    </span>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>

      <section id="faq" style={section}>
        <div style={container}>
          <div style={title}>
            <div style={eyebrow}>FAQ</div>
            <h2
              style={{
                fontFamily: "Georgia,serif",
                fontSize: "clamp(36px,5vw,58px)",
                color: "#092338",
                marginBottom: 18,
              }}
            >
              Questions before we begin?
            </h2>
            <p style={{ fontSize: 17, lineHeight: 1.8, color: "#637181" }}>
              Here are answers to some of the things clients ask us most often.
            </p>
          </div>

          <div style={{ maxWidth: 850, margin: "auto" }}>
            {faqs.map(([question, answer], index) => (
              <div
                key={question}
                style={{
                  borderBottom: "1px solid #e1d8ca",
                }}
              >
                <button
                  onClick={() =>
                    setActiveFaq(activeFaq === index ? -1 : index)
                  }
                  aria-expanded={activeFaq === index}
                  style={{
                    width: "100%",
                    padding: "23px 0",
                    background: "transparent",
                    border: 0,
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center",
                    textAlign: "left",
                    cursor: "pointer",
                    color: "#092338",
                    fontSize: 16,
                    fontWeight: 800,
                    gap: 20,
                  }}
                >
                  <span>{question}</span>
                  <span
                    style={{
                      fontSize: 24,
                      color: "#c89032",
                      minWidth: 25,
                      textAlign: "center",
                    }}
                  >
                    {activeFaq === index ? "−" : "+"}
                  </span>
                </button>

                {activeFaq === index && (
                  <div
                    style={{
                      padding: "0 40px 22px 0",
                      color: "#637181",
                      lineHeight: 1.8,
                      fontSize: 14,
                    }}
                  >
                    {answer}
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      </section>

      <section
        id="contact"
        style={{
          ...section,
          background: "linear-gradient(135deg,#071f32,#123b52)",
          color: "#fff",
        }}
      >
        <div
          style={{
            ...container,
            display: "grid",
            gridTemplateColumns: "repeat(auto-fit,minmax(320px,1fr))",
            gap: 60,
            alignItems: "start",
          }}
        >
          <div>
            <div style={eyebrow}>Let's Connect</div>

            <h2
              style={{
                fontFamily: "Georgia,serif",
                fontSize: "clamp(40px,5vw,60px)",
                lineHeight: 1.05,
                marginBottom: 20,
              }}
            >
              Have an idea? Let's make it real.
            </h2>

            <p
              style={{
                color: "#b8cad5",
                lineHeight: 1.8,
                marginBottom: 30,
              }}
            >
              Tell us what you are building, what you want to improve or simply
              where you want to go next. We would love to hear the story behind
              your idea.
            </p>

            <div style={{ display: "grid", gap: 18 }}>
              {[
                ["phone", "Call Us", "+91 9390642779"],
                ["mail", "Email Us", "vighnex@gmail.com"],
                ["location", "Location", "Banglore, India"],
              ].map(([icon, label, value]) => (
                <div
                  key={label}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 14,
                  }}
                >
                  <div
                    style={{
                      width: 43,
                      height: 43,
                      borderRadius: 13,
                      background: "rgba(230,184,92,.13)",
                      color: "#e6b85c",
                      display: "grid",
                      placeItems: "center",
                    }}
                  >
                    <Icon type={icon} size={19} />
                  </div>

                  <div>
                    <strong style={{ display: "block", fontSize: 13 }}>
                      {label}
                    </strong>
                    <span style={{ fontSize: 12, color: "#adc0cb" }}>
                      {value}
                    </span>
                  </div>
                </div>
              ))}
            </div>

            <img
              src="https://images.unsplash.com/photo-1556761175-5973dc0f32e7?auto=format&fit=crop&w=900&q=85"
              alt="Digital collaboration"
              loading="lazy"
              style={{
                width: "100%",
                maxWidth: 480,
                height: 210,
                objectFit: "cover",
                borderRadius: 20,
                marginTop: 35,
                opacity: 0.85,
              }}
            />
          </div>

          {formStatus === "success" ? (
            <div
              style={{
                background: "#fff",
                color: "#092338",
                borderRadius: 25,
                padding: 45,
                textAlign: "center",
                boxShadow: "0 25px 60px rgba(0,0,0,.2)",
              }}
            >
              <div
                style={{
                  width: 70,
                  height: 70,
                  borderRadius: "50%",
                  background: "#fff1cf",
                  color: "#c89032",
                  display: "grid",
                  placeItems: "center",
                  margin: "0 auto 20px",
                }}
              >
                <Icon type="check" size={35} />
              </div>

              <h3
                style={{
                  fontFamily: "Georgia,serif",
                  fontSize: 30,
                  marginBottom: 12,
                }}
              >
                Thank You!
              </h3>

              <p style={{ color: "#637181", lineHeight: 1.7 }}>
                Your message has been sent successfully. Our team will get back
                to you soon.
              </p>

              <button
                onClick={() => setFormStatus("idle")}
                style={{
                  ...button,
                  marginTop: 25,
                  background: "#092338",
                  color: "#fff",
                }}
              >
                Send Another Message
              </button>
            </div>
          ) : (
            <form
              onSubmit={handleSubmit}
              style={{
                background: "#fff",
                color: "#092338",
                borderRadius: 25,
                padding: 32,
                boxShadow: "0 25px 60px rgba(0,0,0,.2)",
              }}
            >
              <h3
                style={{
                  fontFamily: "Georgia,serif",
                  fontSize: 30,
                  marginBottom: 22,
                }}
              >
                Start a conversation
              </h3>

              <div
                style={{
                  display: "grid",
                  gridTemplateColumns: "repeat(auto-fit,minmax(210px,1fr))",
                  gap: 15,
                }}
              >
                {[
                  ["name", "YOUR NAME", "Enter your name", "text", true],
                  ["email", "EMAIL ADDRESS", "you@example.com", "email", true],
                  ["phone", "PHONE NUMBER", "+91 XXXXX XXXXX", "tel", false],
                ].map(([name, label, placeholder, type, required]) => (
                  <label
                    key={name}
                    style={{
                      display: "block",
                    }}
                  >
                    <span
                      style={{
                        display: "block",
                        fontSize: 11,
                        fontWeight: 800,
                        marginBottom: 7,
                        color: "#556575",
                      }}
                    >
                      {label}
                    </span>

                    <input
                      type={type}
                      name={name}
                      placeholder={placeholder}
                      required={required}
                      style={{
                        width: "100%",
                        border: "1px solid #e1e5e8",
                        borderRadius: 12,
                        padding: 14,
                        fontFamily: "inherit",
                        outline: "none",
                        background: "#fbfcfd",
                      }}
                    />
                  </label>
                ))}

                <label style={{ display: "block" }}>
                  <span
                    style={{
                      display: "block",
                      fontSize: 11,
                      fontWeight: 800,
                      marginBottom: 7,
                      color: "#556575",
                    }}
                  >
                    SERVICE
                  </span>

                  <select
                    name="choice"
                    defaultValue=""
                    required
                    style={{
                      width: "100%",
                      border: "1px solid #e1e5e8",
                      borderRadius: 12,
                      padding: 14,
                      fontFamily: "inherit",
                      outline: "none",
                      background: "#fbfcfd",
                    }}
                  >
                    <option value="" disabled>
                      Select a service
                    </option>
                    <option>Web Development</option>
                    <option>UI/UX Design</option>
                    <option>Digital Marketing</option>
                    <option>Mobile Development</option>
                    <option>Cloud Development</option>
                    <option>Complete Digital Solution</option>
                  </select>
                </label>

                <label
                  style={{
                    display: "block",
                    gridColumn: "1/-1",
                  }}
                >
                  <span
                    style={{
                      display: "block",
                      fontSize: 11,
                      fontWeight: 800,
                      marginBottom: 7,
                      color: "#556575",
                    }}
                  >
                    PROJECT DETAILS
                  </span>

                  <textarea
                    name="message"
                    rows={5}
                    placeholder="Tell us a little about your idea, goals or requirements..."
                    required
                    style={{
                      width: "100%",
                      border: "1px solid #e1e5e8",
                      borderRadius: 12,
                      padding: 14,
                      fontFamily: "inherit",
                      outline: "none",
                      background: "#fbfcfd",
                      resize: "vertical",
                    }}
                  />
                </label>
              </div>

              <button
                type="submit"
                disabled={formStatus === "sending"}
                style={{
                  ...button,
                  width: "100%",
                  marginTop: 8,
                  background:
                    formStatus === "sending"
                      ? "#c7a35f"
                      : "linear-gradient(135deg,#e6b85c,#c89032)",
                  color: "#152536",
                  opacity: formStatus === "sending" ? 0.8 : 1,
                }}
              >
                {formStatus === "sending"
                  ? "Sending..."
                  : "Send Enquiry"}{" "}
                <Icon type="arrow" size={17} />
              </button>

              {formStatus === "error" && (
                <p
                  style={{
                    marginTop: 14,
                    color: "#c0392b",
                    fontSize: 13,
                    textAlign: "center",
                  }}
                >
                  Something went wrong — please try again.
                </p>
              )}

              <p
                style={{
                  marginTop: 12,
                  fontSize: 11,
                  color: "#888",
                  textAlign: "right",
                }}
              >
                Powered by{" "}
                <a
                  href="https://splitforms.com"
                  target="_blank"
                  rel="sponsored noopener"
                  style={{
                    color: "#888",
                    textDecoration: "none",
                  }}
                >
                  splitforms
                </a>
              </p>
            </form>
          )}
        </div>
      </section>

      <footer
        style={{
          background: "#061b2b",
          color: "#b7c7d0",
          padding: "55px 0 22px",
        }}
      >
        <div style={container}>
          <div
            style={{
              display: "grid",
              gridTemplateColumns: "1.5fr 1fr 1fr 1fr",
              gap: 40,
              paddingBottom: 40,
            }}
          >
            <div>
              <img
                src={logo}
                alt="Vighnex Technologies"
                style={{
                  width: 205,
                  height: 65,
                  objectFit: "contain",
                  objectPosition: "left center",
                  display: "block",
                  filter: "brightness(0) invert(1)",
                }}
              />

              <p
                style={{
                  fontSize: 13,
                  lineHeight: 1.8,
                  maxWidth: 320,
                  marginTop: 14,
                  color: "#aebec8",
                }}
              >
                Building meaningful digital experiences where traditional
                values meet modern technology. Create. Build. Deploy. Grow.
              </p>
            </div>

            {[
              [
                "Company",
                [
                  ["About Us", "about"],
                  ["Why Choose Us", "why"],
                  ["Our Work", "projects"],
                  ["Contact", "contact"],
                ],
              ],
              [
                "Services",
                [
                  ["Web Development", "services"],
                  ["UI/UX Design", "services"],
                  ["Digital Marketing", "services"],
                  ["Mobile Development", "services"],
                  ["Cloud Development", "services"],
                ],
              ],
              [
                "Let's Connect",
                [
                  ["Start a Project", "contact"],
                  ["FAQs", "faq"],
                  ["Technology", "technology"],
                  ["Our Process", "process"],
                ],
              ],
            ].map(([heading, links]) => (
              <div key={heading}>
                <h4
                  style={{
                    color: "#fff",
                    marginBottom: 17,
                    fontSize: 14,
                  }}
                >
                  {heading}
                </h4>

                <div style={{ display: "grid", gap: 10 }}>
                  {links.map(([text, id]) => (
                    <button
                      key={text}
                      onClick={() => scrollTo(id)}
                      style={{
                        background: "transparent",
                        border: 0,
                        color: "#aebec8",
                        textAlign: "left",
                        cursor: "pointer",
                        fontSize: 12,
                        padding: 0,
                      }}
                    >
                      {text}
                    </button>
                  ))}
                </div>
              </div>
            ))}
          </div>

          <div
            style={{
              borderTop: "1px solid rgba(255,255,255,.1)",
              paddingTop: 22,
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              gap: 20,
              flexWrap: "wrap",
              fontSize: 11,
            }}
          >
            <span>© 2026 Vighnex Technologies. All Rights Reserved.</span>

            <div style={{ display: "flex", gap: 8 }}>
              {[
                ["in", "https://www.linkedin.com"],
                ["◎", "https://www.instagram.com"],
                ["f", "https://www.facebook.com"],
                ["▶", "https://www.youtube.com"],
              ].map(([text, href]) => (
                <a
                  key={href}
                  href={href}
                  target="_blank"
                  rel="noreferrer"
                  style={{
                    width: 34,
                    height: 34,
                    border: "1px solid #385263",
                    borderRadius: "50%",
                    display: "grid",
                    placeItems: "center",
                    color: "#c4d2d9",
                    textDecoration: "none",
                  }}
                >
                  {text}
                </a>
              ))}
            </div>
          </div>
        </div>
      </footer>
    </div>
  );
}
